# ==============================================================================# 088_COMMERCIAL_DATA_LAKE_ENGINE.py## IOTEC COMMERCIAL DATA LAKE ENGINE## Missão:# Gerenciar o Data Lake Comercial.## Não normaliza.# Não altera dados.# Apenas cataloga datasets brutos.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CommercialDataLakeEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_data_lake(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            lake_id TEXT,            dataset_id TEXT,            provider TEXT,            adapter TEXT,            capability TEXT,            dataset_version INTEGER,            record_count INTEGER,            storage_status TEXT,            dataset_hash TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ---------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ---------------------------------------------------------------------    def ingest_dataset(self, dataset):        version = self.conn.execute("""            SELECT COALESCE(MAX(dataset_version),0)+1            FROM commercial_data_lake            WHERE dataset_hash=?        """, (dataset["hash"],)).fetchone()[0]        payload = {            "timestamp": datetime.utcnow().isoformat(),            "lake_id": hashlib.md5(                f'{dataset["dataset_id"]}{version}'.encode()            ).hexdigest(),            "dataset_id": dataset["dataset_id"],            "provider": dataset["provider"],            "adapter": dataset["adapter"],            "capability": dataset["capability"],            "dataset_version": version,            "record_count": dataset["record_count"],            "storage_status": "STORED",            "dataset_hash": dataset["hash"],            "metadata": {                "origin": "087_COMMERCIAL_DATA_COLLECTION_ENGINE"            }        }        assinatura = self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_data_lake(            timestamp,            lake_id,            dataset_id,            provider,            adapter,            capability,            dataset_version,            record_count,            storage_status,            dataset_hash,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["lake_id"],            payload["dataset_id"],            payload["provider"],            payload["adapter"],            payload["capability"],            payload["dataset_version"],            payload["record_count"],            payload["storage_status"],            payload["dataset_hash"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"] = assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    conn = sqlite3.connect(DB)    conn.row_factory = sqlite3.Row    dataset = conn.execute("""        SELECT *        FROM commercial_raw_dataset        ORDER BY id DESC        LIMIT 1    """).fetchone()    if dataset is None:        raise RuntimeError("Nenhum dataset encontrado.")    engine = CommercialDataLakeEngine()    resultado = engine.ingest_dataset(dict(dataset))    print("="*80)    print("COMMERCIAL DATA LAKE")    print("="*80)    for k, v in resultado.items():        print(f"{k:22}: {v}")    print("="*80)